//! The weekly Torah portion (парашат а-шавуа).
//!
//! The annual cycle depends only on the year type (keviyah: the weekday of
//! Rosh Hashana and the year length — 14 types) and on Israel vs diaspora.
//! As in common calendar software (e.g. hebcal), the reading for every
//! Shabbat of each year type is kept in a table (`parasha_tables.rs`,
//! generated by tools/gen_parasha_tables.py and cross-checked in the tests
//! against known Shabbatot). The tables follow the Shulchan Aruch rules
//! (OC 428): Nitzavim before Rosh Hashana, Devarim before Tisha BeAv,
//! Bamidbar before Shavuot, the seven possible double portions.

use chrono::{Datelike, Duration, NaiveDate, Weekday};

use crate::calendar::hebrew::{new_year, HebrewDate, TISHREI};
use crate::i18n::tr;

include!("parasha_tables.rs");

