/// What is read on a Shabbat.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Reading {
    /// One portion (0 = Bereshit … 53 = Vezot HaBeracha).
    Parasha(u8),
    /// Two portions read together (n, n+1).
    Double(u8, u8),
    /// A festival Shabbat with its own reading instead of the weekly portion.
    Festival,
}

impl Reading {
    /// «Ваякгель — Пкудей».
    pub fn name_ru(self) -> String {
        match self {
            Reading::Parasha(n) => tr(PARASHOT[n as usize].1).to_string(),
            Reading::Double(a, b) => crate::trf!(
                "{} — {}",
                "{}-{}",
                tr(PARASHOT[a as usize].1),
                tr(PARASHOT[b as usize].1)
            ),
            Reading::Festival => tr("Праздничное чтение").to_string(),
        }
    }

    pub fn name_he(self) -> String {
        match self {
            Reading::Parasha(n) => PARASHOT[n as usize].2.to_string(),
            Reading::Double(a, b) => {
                format!("{}–{}", PARASHOT[a as usize].2, PARASHOT[b as usize].2)
            }
            Reading::Festival => String::new(),
        }
    }

    /// Portion indices (for texts lookups).
    pub fn indices(self) -> Vec<u8> {
        match self {
            Reading::Parasha(n) => vec![n],
            Reading::Double(a, b) => vec![a, b],
            Reading::Festival => vec![],
        }
    }
}

/// Reading on the Shabbat `shabbat` (any other weekday is moved to the
/// following Shabbat).
pub fn reading_on(shabbat: NaiveDate, diaspora: bool) -> Reading {
    let sat = next_shabbat(shabbat);
    let hy = HebrewDate::from_gregorian(sat).year;
    // The year's first Shabbat on or after 1 Tishrei.
    let rh = crate::calendar::hebrew::gregorian_from_fixed(new_year(hy));
    debug_assert_eq!(HebrewDate::from_gregorian(rh).month, TISHREI);
    let first = next_shabbat(rh);
    let idx = ((sat - first).num_days() / 7) as usize;
    let key = (
        rh.weekday().num_days_from_sunday() as u8 + 1,
        crate::calendar::hebrew::days_in_year(hy) as u16,
    );
    let row = TABLES
        .iter()
        .find(|(k, _)| *k == key)
        .map(|(_, rows)| rows[if diaspora { 0 } else { 1 }])
        .expect("all 14 year types are tabulated");
    match row.get(idx).copied().unwrap_or(-1) {
        v if v < 0 => Reading::Festival,
        v if v >= 100 => Reading::Double((v - 100) as u8, (v - 99) as u8),
        v => Reading::Parasha(v as u8),
    }
}

/// The Shabbat on or after `d`.
pub fn next_shabbat(d: NaiveDate) -> NaiveDate {
    let ahead = (Weekday::Sat.num_days_from_monday() + 7 - d.weekday().num_days_from_monday()) % 7;
    d + Duration::days(ahead as i64)
}

/// «Parasha of the week» for `date`: the reading of the coming Shabbat (or
/// today's, on Shabbat). When that Shabbat has a festival reading, the next
/// weekly portion is returned too.
pub fn weekly(
    date: NaiveDate,
    diaspora: bool,
) -> (NaiveDate, Reading, Option<(NaiveDate, Reading)>) {
    let sat = next_shabbat(date);
    let r = reading_on(sat, diaspora);
    let next = if r == Reading::Festival {
        let mut s = sat;
        let mut found = None;
        for _ in 0..4 {
            s += Duration::days(7);
            let rr = reading_on(s, diaspora);
            if rr != Reading::Festival {
                found = Some((s, rr));
                break;
            }
        }
        found
    } else {
        None
    };
    (sat, r, next)
}
